back=[(72,1),(87,5),(104,0),(106,10),(114,5),(115,21),(123,18),(121,28),(131,37),(125,41),(131,48),(126,55),(131,65),(130,76),(132,79),(131,89),(121,96),(115,96),(112,107),(109,110),(109,115),(126,124),(140,135),(150,157),(157,174),(153,178),(160,193),(165,219),(166,237),(171,254),(168,266),(160,272),(149,269),(146,260),(142,255),(147,246),(155,240),(152,223),(146,200),(135,178),(130,183),(129,215),(133,235),(138,256),(141,278),(137,284),(131,287),(136,306),(139,320),(140,343),(146,357),(158,366),(163,375),(161,384),(153,389),(129,389),(122,385),(121,375),(121,363),(117,350),(113,332),(110,310),(106,295),(94,290),(91,285),(87,265),(83,263),(76,289),(69,290),(66,307),(61,332),(55,348),(55,360),(58,374),(56,384),(48,388),(32,386),(16,390),(9,382),(8,375),(13,368),(30,355),(31,344),(32,326),(38,306),(40,287),(30,282),(34,271),(41,241),(43,235),(49,199),(46,179),(35,196),(25,215),(22,232),(21,240),(26,249),(29,263),(22,270),(14,272),(4,267),(1,260),(4,247),(8,232),(11,209),(20,187),(24,177),(16,171),(24,158),(28,143),(34,134),(43,126),(68,116),(68,107),(62,103),(58,94),(49,95),(44,92),(41,86),(42,79),(46,74),(45,60),(42,50),(46,39),(43,35),(52,26),(46,24),(57,21),(60,14),(64,15)]
for name,box,pts in [('front',(548,100,733,498),front),('back',(746,106,919,499),back)]:
 rgb=np.array(src.crop(box));h,w=rgb.shape[:2]
 poly=np.zeros((h,w),np.uint8);cv2.fillPoly(poly,[np.array(pts,np.int32)],255)
 inside=cv2.erode(poly,np.ones((3,3),np.uint8))
 outside=cv2.dilate(poly,np.ones((9,9),np.uint8))
 mask=np.where(outside,cv2.GC_PR_BGD,cv2.GC_BGD).astype('uint8')
 mask[poly>0]=cv2.GC_PR_FGD;mask[inside>0]=cv2.GC_FGD
 cv2.grabCut(rgb,mask,None,np.zeros((1,65)),np.zeros((1,65)),3,cv2.GC_INIT_WITH_MASK)
 fg=((mask==cv2.GC_FGD)|(mask==cv2.GC_PR_FGD)).astype('uint8')*255
 # Restrict to the traced body and remove tiny isolated background specks.
 fg=cv2.bitwise_and(fg,outside)
 num,labels,stats,_=cv2.connectedComponentsWithStats(fg)
 if num>1:fg=(labels==(1+stats[1:,cv2.CC_STAT_AREA].argmax())).astype('uint8')*255
 alpha=cv2.GaussianBlur(fg,(3,3),.38)
 rgba=np.dstack([rgb,alpha]);rgba[alpha==0,:3]=0
 Image.fromarray(rgba).save('public/art/player-'+name+'.png')
 print(name,w,h,'opaque pixels',int((alpha>200).sum()))
